<script setup lang="ts">
import {useOffice} from '../Office/context';
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {getSession} from '../FleetAndDocuments/api';
import type {Session} from '../FleetAndDocuments/contracts';
import { useModuleRequests } from '../Office/useModuleRequests';
import {failure,ApiError} from '../Administration/api';
const {all,request,paginated}=useModuleRequests();
import {calendarDate,registrationDate} from '../FleetAndDocuments/presentation';
import SearchSelect from '../Workshop/components/SearchSelect.vue';
interface Alert {id:string;document_type_id:string;document_type:string;asset:{id:string;code:string;type:string};expires_on:string;days_remaining:number;status:'expired'|'expiring_soon';review:null|{at:string;by:{id:string;name:string};validity_at_review:string};original_href:string}
const props=defineProps<{session:Session|null}>();const emit=defineEmits<{denied:[error:unknown];lock:[locked:boolean]}>();
const initial=new URLSearchParams(location.search),status=ref(['expired','expiring_soon'].includes(initial.get('status')??'')?initial.get('status')!:'');
const attention=ref(['reviewed','unreviewed'].includes(initial.get('attention')??'')?initial.get('attention')!:'');
const asset=ref(''),assetType=ref(''),type=ref(''),from=ref(''),to=ref(''),page=ref(1),last=ref(1),total=ref(0),loading=ref(false),busy=ref(false),rows=ref<Alert[]>([]),error=ref(''),success=ref(''),pending=ref('');
const assets=ref<{value:string;label:string}[]>([]),types=ref<{value:string;label:string}[]>([]),lookupError=ref(''),conflict=ref(false);
const officeHost=useOffice(()=>busy.value||!!pending.value);const recovery=officeHost?.recovery<string>('alerts')??new Map<string,string>();let generation=0,actorGeneration=0;
const allowed=computed(()=>props.session?.roles.some(r=>['administrator','secretary'].includes(r))??false),locked=computed(()=>busy.value||!!pending.value);
function report(e:unknown):void{const problem=failure(e);error.value=problem.message;if(Object.keys(problem.fields).length)error.value+=' '+Object.values(problem.fields).flat().join(' ');if([401,403].includes(problem.status))emit('denied',problem);}
async function load(target=1):Promise<boolean>{if(!allowed.value)return false;const current=++generation;loading.value=true;rows.value=[];error.value='';try{const q=new URLSearchParams({page:String(target),per_page:'25'});for(const[k,v]of Object.entries({status:status.value,attention:attention.value,fleet_asset_id:asset.value,asset_type:assetType.value,document_type_id:type.value,from:from.value,to:to.value}))if(v)q.set(k,v);const value=await paginated<Alert>(`/document-alerts?${q}`);if(current!==generation)return false;rows.value=value.data;page.value=value.meta.current_page;last.value=value.meta.last_page;total.value=value.meta.total??value.data.length;return true;}catch(e){if(current===generation)report(e);return false;}finally{if(current===generation)loading.value=false;}}
async function lookup():Promise<void>{const current=actorGeneration;lookupError.value='';try{const [a,t]=await Promise.all([all<{id:string;code:string}>('/fleet-assets'),all<{id:string;name:string}>('/document-types')]);if(current!==actorGeneration)return;assets.value=a.map(x=>({value:x.id,label:x.code}));types.value=t.map(x=>({value:x.id,label:x.name}));}catch(e){if(current===actorGeneration){lookupError.value='No se pudieron cargar activos y tipos. Vuelve a consultar.';report(e);}}}
watch(locked,value=>emit('lock',value),{immediate:true});
async function review(id:string):Promise<void>{if(busy.value||!props.session)return;const actor=props.session.id;busy.value=true;success.value='';error.value='';try{const fresh=await getSession();if(fresh.id!==actor)throw new ApiError(403,'La cuenta cambió. Consulta la alerta con la cuenta actual.');recovery.set(actor,id);await request(`/document-alerts/${id}/review`,'POST',{});recovery.delete(actor);if(props.session?.id!==actor)return;pending.value='';conflict.value=false;success.value='Revisión registrada. El documento conserva su vencimiento y estado.';}catch(e){const p=failure(e);if(recovery.has(actor)||p.status===0||p.status>=500||[401,419].includes(p.status)){recovery.set(actor,id);if(props.session?.id===actor)pending.value=id;}if(props.session?.id===actor){conflict.value=p.status===409;report(e);}}finally{busy.value=false;}if(!pending.value&&props.session?.id===actor)await load(page.value);}
async function resolveConflict():Promise<void>{
    if(!conflict.value||busy.value||!props.session)return;
    const actor=props.session.id,id=pending.value;busy.value=true;
    try {
        // 409 is a definitive rejection. Release only this rejected review after
        // an explicit successful refresh; never discard an uncertain operation.
        if(await load(page.value)&&props.session?.id===actor&&pending.value===id){recovery.delete(actor);pending.value='';conflict.value=false;success.value='Conflicto consultado. La revisión rechazada no se ha reenviado.';}
    } finally {busy.value=false;}
}
function confirmReview(id:string):void{if(!locked.value&&confirm('Marcar como revisada. Esto no renueva ni modifica el documento.'))void review(id);}
watch(()=>props.session?`${props.session.id}:${props.session.roles.join('|')}`:'',()=>{generation++;actorGeneration++;rows.value=[];assets.value=[];types.value=[];loading.value=false;pending.value=props.session?recovery.get(props.session.id)??'':'';success.value='';if(allowed.value){void lookup();void load();}},{immediate:true});
onBeforeUnmount(()=>{generation++;actorGeneration++;emit('lock',false);});
</script>
<template><section v-if="allowed" class="space-y-4"><p class="notice-info">Documentos actuales de cabezales y cisternas. Próximos a vencer: hoy a 15 días inclusive; vencidos: fecha anterior a hoy en Costa Rica. Revisada no significa vigente ni resuelta. No se bloquean asignaciones.</p><p class="notice-info">Personal aún no dispone de documentos ni vencimientos en su modelo. No se generan alertas personales ficticias.</p><form data-office-filter class="panel grid gap-3 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="load()"><label>Vencimiento<select v-model="status" aria-label="Vencimiento" class="field" :disabled="loading||locked"><option value="">Todos</option><option value="expired">Vencidos</option><option value="expiring_soon">Próximos a vencer</option></select></label><label>Atención<select v-model="attention" aria-label="Atención" class="field" :disabled="loading||locked"><option value="">Todas</option><option value="unreviewed">Sin revisar</option><option value="reviewed">Revisadas</option></select></label><label>Clase de activo<select v-model="assetType" aria-label="Clase de activo" class="field" :disabled="loading||locked"><option value="">Todos</option><option value="tractor_unit">Cabezal</option><option value="tanker">Cisterna</option></select></label><SearchSelect v-model="asset" :options="assets" label="Activo" :disabled="loading||locked"/><SearchSelect v-model="type" :options="types" label="Tipo documental" :disabled="loading||locked"/><label>Vence desde<input v-model="from" type="date" class="field" :disabled="loading||locked"></label><label>Vence hasta<input v-model="to" type="date" class="field" :min="from||undefined" :disabled="loading||locked"></label><button class="btn-primary" :disabled="loading||locked">Consultar vencimientos</button></form><p v-if="lookupError" role="alert" class="notice-error">{{lookupError}} <button class="btn-secondary" :disabled="locked" @click="lookup">Recargar selectores</button></p><p v-if="loading" role="status">Consultando vencimientos…</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><p v-if="success" role="status" class="notice-success">{{success}}</p><aside v-if="pending" class="panel"><p>Revisión pendiente: {{pending}}</p><template v-if="conflict"><p>El servidor rechazó la revisión con un conflicto. Consulta las alertas actuales para resolverlo explícitamente.</p><button class="btn-secondary" :disabled="busy||loading" @click="resolveConflict">Resolver conflicto consultando alertas actuales</button></template><p>Respuesta pendiente de confirmar. Consulta o reintenta la misma revisión; no se enviará automáticamente.</p><button class="btn-secondary" :disabled="busy" @click="review(pending)">Confirmar la misma revisión</button></aside><div class="panel overflow-x-auto"><table class="data-table"><caption class="text-left font-semibold">Alertas documentales actuales</caption><thead><tr><th>Activo</th><th>Documento</th><th>Vence</th><th>Tiempo</th><th>Estado</th><th>Atención</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.asset.code}} · {{row.asset.type==='tanker'?'Cisterna':'Cabezal'}}</td><td>{{row.document_type}}</td><td>{{calendarDate(row.expires_on)}}</td><td>{{row.days_remaining<0?`${-row.days_remaining} días de atraso`:`${row.days_remaining} días restantes`}}</td><td>{{row.status==='expired'?'Vencido':'Próximo a vencer'}}</td><td>{{row.review?`Revisada por ${row.review.by.name} · ${registrationDate(row.review.at)}`:'Sin revisar'}}<p v-if="row.review">Estado al revisar: {{row.review.validity_at_review==='expired'?'Vencido':'Próximo a vencer'}}</p></td><td><a :href="row.original_href" class="text-blue-800 underline" target="_blank" rel="noopener">Ver registro original</a><button v-if="!row.review" class="btn-secondary" :disabled="locked||loading" @click="confirmReview(row.id)">Marcar revisada</button></td></tr></tbody></table><p v-if="!loading&&!rows.length">No hay vencimientos para estos filtros.</p></div><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||locked||page<=1" @click="load(page-1)">Anterior</button><span>{{total}} alertas · página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||locked||page>=last" @click="load(page+1)">Siguiente</button></div><a href="/documentacion" class="text-blue-800 underline">Abrir Documentación para consultar o renovar</a></section></template>
